    返回 ``{相对路径: (绝对路径, 类型)}``，类型为 'file' 或 'dir'。
    ``root`` 不存在时返回空字典。
    """
    entries: Dict[str, Tuple[str, str]] = {}
    if not os.path.isdir(root):
