    try:
        info = os.stat(path)
    except OSError:
        return None
    return (info.st_size, info.st_mtime_ns)


def files_equal(path1: str, path2: str) -> bool:
    """比较两个文件的内容是否完全相同。"""
    try:
        # 先比较大小，不同则直接返回
        stat1 = os.stat(path1)
        stat2 = os.stat(path2)
        if stat1.st_size != stat2.st_size:
            return False

        # 逐块比较内容
        chunk_size = 1024 * 1024  # 1MB
        with open(path1, "rb") as f1, open(path2, "rb") as f2:
            while True:
                chunk1 = f1.read(chunk_size)
                chunk2 = f2.read(chunk_size)
                if chunk1 != chunk2:
                    return False
                if not chunk1:  # 都读完了
                    break
        return True
    except OSError:
        return False


def is_readonly(path: str) -> bool:
    """路径是否带有只读属性。"""
    try:
        info = os.stat(path)
    except OSError:
        return False
    return not bool(info.st_mode & stat.S_IWRITE)


def clear_readonly(path: str) -> None:
    """清除路径的只读属性（包括目录及其内容）。"""
    try:
        if os.path.isdir(path):
            # 递归清除目录及其所有内容的只读属性
            for root, dirs, files in os.walk(path):
                for name in files:
                    full = os.path.join(root, name)
                    try:
                        if is_readonly(full):
                            os.chmod(full, stat.S_IWRITE | stat.S_IREAD)
                    except OSError:
                        pass
                for name in dirs:
                    full = os.path.join(root, name)
                    try:
                        if is_readonly(full):
                            os.chmod(full, stat.S_IWRITE | stat.S_IREAD)
                    except OSError:
                        pass
            # 清除目录自身
            if is_readonly(path):
                os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
        else:
            # 单个文件
            if is_readonly(path):
                os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
    except OSError:
        pass


def remove_file(path: str) -> None:
    """删除单个文件。"""
    # 尝试清除只读属性
    if is_readonly(path):
        clear_readonly(path)
    os.remove(path)


def remove_tree(path: str) -> None:
    """递归删除一棵目录树。"""
    # 尝试清除只读属性
    if os.path.exists(path):
        clear_readonly(path)
    shutil.rmtree(path)


def copy_file(source: str, target: str) -> None:
    """把 ``source`` 的内容写到 ``target``，必要时创建父目录。

    复制完成后保留源文件的修改时间。
    """
    parent = os.path.dirname(target)
    if parent:
        os.makedirs(parent, exist_ok=True)

    # 如果目标已存在且只读，先清除只读属性
    if os.path.exists(target) and is_readonly(target):
        clear_readonly(target)

    with open(source, "rb") as src_handle, open(target, "wb") as dst_handle:
        shutil.copyfileobj(src_handle, dst_handle, length=1024 * 1024)

    # 保留源文件的修改时间
    try:
        stat_info = os.stat(source)
        os.utime(target, (stat_info.st_atime, stat_info.st_mtime))
    except OSError:
        pass


def prune_empty_dirs(root: str) -> None:
    """自底向上删除目标树中的空目录（不含 ``root`` 自身）。"""
    root = os.path.abspath(root)
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        if os.path.abspath(dirpath) == root:
            continue
        try:
            if not os.listdir(dirpath):
                # 如果是只读目录，先清除只读属性
                if is_readonly(dirpath):
                    clear_readonly(dirpath)
                os.rmdir(dirpath)
        except OSError:
            pass

